import{_ as a,a0 as i,w as s,s as p,ao as u,I as o,x as t,a1 as r,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const M=JSON.parse('{"title":"AMD 的開源圖形驅動程序 Vulkan 現在支持光線追蹤 | LCTT x X-CMD","titleTemplate":false,"description":"AMD 的開源圖形驅動程序 Vulkan 現在支持光線追蹤 | LCTT (202209) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"AMD 的開源圖形驅動程序 Vulkan 現在支持光線追蹤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"AMD 的開源圖形驅動程序 Vulkan 現在支持光線追蹤 | LCTT (202209) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202209/20220919 AMD-s Open Source Vulkan Graphics Drivers Now Enable Ray Tracing","title":"AMD 的開源圖形驅動程序 Vulkan 現在支持光線追蹤","tag":"202209","desc":""},"relativePath":"202209/20220919 AMD-s Open Source Vulkan Graphics Drivers Now Enable Ray Tracing.md","filePath":"[post].md"}'),d={name:"202209/20220919 AMD-s Open Source Vulkan Graphics Drivers Now Enable Ray Tracing.md"};function D(A,e,T,m,f,V){const n=i("Link");return s(),p("div",null,[e[15]||(e[15]=u('<h1 id="amd-的開源圖形驅動程序-vulkan-現在支持光線追蹤" tabindex="-1">AMD 的開源圖形驅動程序 Vulkan 現在支持光線追蹤 <a class="header-anchor" href="#amd-的開源圖形驅動程序-vulkan-現在支持光線追蹤" aria-label="Permalink to “AMD 的開源圖形驅動程序 Vulkan 現在支持光線追蹤”">​</a></h1><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/09/AMD-Ryzen-Zen-CPUs_Next-Gen-1536x842.jpg" alt=""></p><blockquote><p>RDNA 2 GPU 的 Linux 用户可以使用 AMD 的 AMDVLK GPUOpen 開源 Vulkan 驅動程序。</p></blockquote><p>用於 Radeon RX 6000 GPU 的 AMDVLK GPUOpen 圖形驅動程序在過去一週改進了對 64 位光線追蹤的支持。這涵蓋了支持 RDNA 2 圖形的 APU 以及桌面/移動 GPU。所有平台上的所有 AMD Vulkan 驅動程序現在都支持硬件光線追蹤，包括 Mesa3D RADV、AMDVLK GPUOpen 和 AMDGPU-PRO。</p><p>GPU 光線追蹤庫（GPURT）的基礎是一個 C++ 接口。根據其用法和依賴關係，公共接口被拆分為各種頭文件。用户可以在官方的 GitHub 倉庫上了解更多信息，它還包括了 RDNA 2 GPURT 的結構細分。最新的 AMDVLK GPUOpen v-2022.Q3.4 信息如下：</p><p><strong>更新和新功能：</strong></p><ul><li>擴展 Navi2x 的 64 位光線追蹤功能。</li><li>將 Vulkan 標頭升級到版本 1.3.225</li><li>遊戲性能優化，包括《榮耀戰魂》和《奇點灰燼》</li></ul><p><strong>已解決的問題：</strong></p><ul><li><code>dEQP-VK.api.copy_and_blit.*.resolve_image.whole_copy_before_resolving_transfer.*</code> 新版本 CTS 失敗。</li><li>dEQP-VK.pipeline.creation 緩存控件有一個 CTS 警告。</li><li>Ubuntu 22.04 上的 Firefox 損壞</li><li>VulkanInfo 崩潰，管道緩存已停用</li><li>RX 6800 上的 RGP 測試套件故障</li></ul><p>新的改進包括 GPU 光線追蹤庫（GPURT），它將包括使用 HLSL 之類的着色器在光線追蹤中看到的邊界體積層次（BVH）的構造和排序處理。這個庫將提供一個標準庫來改進圖形渲染並引入更多的統一性。DirectX 12 DXR 也將與新庫一起使用。</p><p>對 GPU 光線追蹤（GPURT）庫的描述為“一個靜態庫（源代碼交付），為支持 DXR（DirectX 12）和 Vulkan® RT API 的 AMD 驅動程序提供與光線追蹤相關的功能。” 該公司的平台抽象庫用於構建庫（PAL）。</p><p>用户可參考最新 AMDVLK GPUOpen v-2022.Q3.4 升級的安裝説明。用户在更新任何軟件、硬件或驅動程序之前應備份所有相關數據，以免丟失重要文件。</p><p>為了讓最新的 Linux 驅動程序為 AMD、Intel 和 NVIDIA 技術做好準備，已經投入了大量工作，這些技術都是在今年第一季度推出的。</p><hr>',14)),o("p",null,[e[1]||(e[1]=t("via: ",-1)),r(n,{href:"https://www.opensourceforu.com/2022/09/amds-open-source-vulkan-graphics-drivers-now-enable-ray-tracing/"},{default:l(()=>[...e[0]||(e[0]=[t("https://www.opensourceforu.com/2022/09/amds-open-source-vulkan-graphics-drivers-now-enable-ray-tracing/",-1)])]),_:1})]),o("p",null,[e[6]||(e[6]=t("作者：",-1)),r(n,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:l(()=>[...e[2]||(e[2]=[t("Laveesh Kocher",-1)])]),_:1}),e[7]||(e[7]=t(" 選題：",-1)),r(n,{href:"https://github.com/lkxed"},{default:l(()=>[...e[3]||(e[3]=[t("lkxed",-1)])]),_:1}),e[8]||(e[8]=t(" 譯者：",-1)),r(n,{href:"https://github.com/littlebirdnest"},{default:l(()=>[...e[4]||(e[4]=[t("littlebirdnest",-1)])]),_:1}),e[9]||(e[9]=t(" 校對：",-1)),r(n,{href:"https://github.com/wxy"},{default:l(()=>[...e[5]||(e[5]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[12]||(e[12]=t("本文由 ",-1)),r(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原創編譯，",-1)),r(n,{href:"https://linux.cn/"},{default:l(()=>[...e[11]||(e[11]=[t("Linux中國",-1)])]),_:1}),e[14]||(e[14]=t(" 榮譽推出",-1))])])}const g=a(d,[["render",D]]);export{M as __pageData,g as default};
